package com.bank.narr.service;

import java.util.logging.Logger;

// Longest common contiguous substring via a 2D run table.
public class NarrationCompareService {
    private static final Logger log = Logger.getLogger(NarrationCompareService.class.getName());

    public int longestSharedRun(String a, String b) {
        int m = a.length(), n = b.length();
        int[][] dp = new int[m + 1][n + 1];         // dp[i][j] run ending at a[i-1], b[j-1]
        int best = 0;
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (a.charAt(i - 1) == b.charAt(j - 1)) {
                    dp[i][j] = 1 + dp[i - 1][j - 1]; // extend the diagonal run
                    best = Math.max(best, dp[i][j]);
                } else {
                    dp[i][j] = 0;                   // contiguity broken, reset
                }
            }
        }
        final int r = best;
        log.info(() -> "Longest shared narration run = " + r);
        return best;
    }
}
